#include <sstream>
#include <string>
#include <tuple>

template <typename... Ts>
std::string tupleText(const std::tuple<Ts...>& t)
{
    std::ostringstream out{};
    out << '(';
    std::apply([&out](const Ts&... items)
    {
        bool first{ true };
        ((out << (first ? "" : ", ") << items, first = false), ...);
        (void)first;
    }, t);
    out << ')';
    return out.str();
}

template <typename... Ts, typename F>
void forEach(const std::tuple<Ts...>& t, F function)
{
    std::apply([&function](const Ts&... items) { (function(items), ...); }, t);
}

unitTests:
TEST("tupleText") { CHECK_EQ(tupleText(std::tuple{ 1, std::string{ "two" }, 3.5 }), "(1, two, 3.5)"); CHECK_EQ(tupleText(std::tuple{ 'x' }), "(x)"); CHECK_EQ(tupleText(std::tuple<>{}), "()"); }
TEST("forEach visits every element in order") { std::string seen; forEach(std::tuple{ 1, 'b', std::string{ "c" } }, [&seen](const auto& item) { std::ostringstream o; o << item; seen += o.str(); }); CHECK_EQ(seen, "1bc"); }
TEST("forEach with a counting visitor") { int count{ 0 }; forEach(std::tuple{ 1.5, 2, 3L, 'x', "five" }, [&count](const auto&) { ++count; }); CHECK_EQ(count, 5); }

